/* From Uiverse.io by Pradeepsaranbishnoi - Tags: loader */
.loader {
  display: flex;
  justify-content: center;
  align-items: center;
  height: 100%;
}

.cube {
  position: relative;
  width: 50px;
  height: 50px;
  transform-style: preserve-3d;
  animation: rotate-cube 2s infinite;
}

.face1,
.face2,
.face3,
.face4,
.face5,
.face6 {
  position: absolute;
  width: 50px;
  height: 50px;
  background-color: transparent;
  border: 2px solid #00BFFF;
  box-sizing: border-box;
}

.face1 {
  transform: rotateY(0deg) translateZ(25px);
  animation: change-color 2s infinite;
}

.face2 {
  transform: rotateX(90deg) translateZ(25px);
}

.face3 {
  transform: rotateY(90deg) translateZ(25px);
  animation: change-color 2s infinite;
}

.face4 {
  transform: rotateY(180deg) translateZ(25px);
  animation: change-color 2s infinite;
}

.face5 {
  transform: rotateX(-90deg) translateZ(25px);
}

.face6 {
  transform: rotateY(-90deg) translateZ(25px);
  animation: change-color 2s infinite;
}

@keyframes rotate-cube {
  from {
    transform: rotateX(0deg) rotateY(0deg);
  }

  to {
    transform: rotateX(360deg) rotateY(360deg);
  }
}

@keyframes change-color {
  0% {
    background-color: #00BFFF;
  }

  25% {
    background-color: #FF1493;
  }

  50% {
    background-color: #32CD32;
  }

  75% {
    background-color: #FFA500;
  }

  100% {
    background-color: #00BFFF;
  }
}

/* From Uiverse.io by pradipkaityuiux - Tags: loading, loader, circle loader, click animation, line loader, loading animation, bounce animation */
.loader {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 150px;
  height: 150px;
  background: transparent;
  border: 3px solid rgba(0, 102, 255, 0.1);
  border-radius: 50%;
  text-align: center;
  line-height: 150px;
  font-family: sans-serif;
  font-size: 20px;
  color: #0066ff;
  letter-spacing: 2px;
  text-transform: uppercase;
  text-shadow: 0 0 10px #0066ff;
  box-shadow: 0 0 20px rgba(0, 0, 0, .15);
}

.loader::before {
  content: '';
  position: absolute;
  top: -3px;
  left: -3px;
  width: 100%;
  height: 100%;
  border: 3px solid transparent;
  border-top: 3px solid #0066ff;
  border-right: 3px solid #0066ff;
  border-radius: 50%;
  animation: animateC 2s linear infinite;
}

.loader span {
  display: block;
  position: absolute;
  top: calc(50% - 2px);
  left: 50%;
  width: 50%;
  height: 4px;
  background: transparent;
  transform-origin: left;
  animation: animate 2s linear infinite;
}

.loader span::before {
  content: '';
  position: absolute;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #00aeff;
  top: -6px;
  right: -8px;
  box-shadow: 0 0 20px 5px #0066ff;
}

@keyframes animateC {
  0% {
    transform: rotate(0deg);
  }

  100% {
    transform: rotate(360deg);
  }
}

@keyframes animate {
  0% {
    transform: rotate(45deg);
  }

  100% {
    transform: rotate(405deg);
  }
}

