  right: 0;
  bottom: 0;
  left: 0;
  z-index: -1;
  margin: -3px;
  border-radius: inherit;
  background: linear-gradient(to bottom, #ccc, #666);
}
.button:after {
  content: "";
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  background: linear-gradient(to bottom, #eee, #ddd);
  border-radius: 15px;
}
.button-content {
  position: absolute;
  top: 50%;
  left: 0;
  right: 0;
  z-index: 1;
  transform: translateY(-50%);
}
.button-content:before {
  content: "";
  position: absolute;
  z-index: -1;
  top: calc(-50% - 2.5px);
  right: 5px;
  bottom: 5px;
  left: 5px;
  background: linear-gradient(to bottom, #dfdfdf, #efefef);
  border-radius: 500px;
  height: 50px;
  transition: opacity 0.3s 0.3s;
  filter: blur(1px);
