  grid-area: 1 / 1;
  flex-flow: column nowrap;
  justify-content: center;
  align-items: center;
  gap: .5rem;
  font-size: 1.1rem;
  text-transform: lowercase;
  font-style: italic;
  opacity: 0;
  animation: item-fade var(--item-duration) infinite ease-in-out;
  animation-delay: calc(var(--idx) * var(--item-duration) / 3);
