button {
  --flight-duration: 3s;
  position: relative;
  width: 100%;
  display: flex;
  flex-flow: row nowrap;
  justify-content: center;
  align-items: center;
  column-gap: 1ch;
  border: none;
  border-bottom: 2px solid rgb(189, 188, 141);
  border-top: 2px solid rgb(189, 188, 141);
  border-radius: .9rem;
  background-color: transparent;
  color: rgb(189, 188, 141);
  padding: 1rem 2rem;
  font-size: 1.2rem;
  font-weight: bold;
  cursor: pointer;
  transition: all 200ms ease-out;
  backdrop-filter: blur(20px);
}

button::before,
button::after {
  offset-path: path('m 0 10 c 8 -25 0 -45 400 -400');
  position: absolute;
  left: -30px;
  opacity: 0;
}

button::before {
  content: '🚀';
  transform: rotate(60deg);
  z-index: 1;
}

button::after {
  content: '💨';
  z-index: 0;
  transform: scale(0) rotate(180deg);
}

button:hover {
  color: var(--space-col);
  border-color: transparent;
  background-color: rgba(229, 202, 69, 0.637);
}

button:hover::before {
  animation: rocket-flight var(--flight-duration) infinite ease-in-out;
}

button:hover::after {
  z-index: 0;
  transform: rotate(180deg);
  animation: rocket-start var(--flight-duration) infinite ease-in-out;
}


