}

.search-icon {
  position: absolute;
  left: 1.5rem;
  top: 50%;
  opacity: 0.7;
  width: 32px;
  height: 32px;
  translate: 0 -50%;
}

.input-wrapper input {
  padding-top: 1rem;
  padding-bottom: 1rem;
  padding-right: 5rem;
  padding-left: 5rem;
  outline-style: none;
