}

.popup {
  display: none;
  padding: 10px 20px;
  position: absolute;
  width: 200px;
  top: -100%;
  left: -25%;
  background-color: var(--bg-light);
  border: 1.5px solid var(--dark-alternative);
  border-radius: 2px;
  animation: slideIn 1s;
}

.toggle-checkbox {
  display: none;
}

.toggle-label {
  position: relative;
  padding: 10px;
  background-color: var(--main-color);
  color: var(--dark-color);
  font-weight: 600;
  cursor: help;
  display: inline-block;
  border: 2px solid var(--dark-color);
  border-radius: 3px;
  box-shadow: 2px 2px var(--dark-color);
  transition: 0.5s;
}

.toggle-label::before {
  content: "";
  position: absolute;
  z-index: -1;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  animation: pulsate 0.7s infinite;
}

.toggle-label:hover::before {
  animation: none;
}

.toggle-label:active {
  transform: translate(2px, 2px);
  box-shadow: 0px 0px var(--dark-color);
}

.close-label {
  position: absolute;
  top: 5px;
  right: 5px;
  width: 20px;
  height: 20px;
}
