  content: "⊗";
  font-size: 22px;
  position: absolute;
  top: -7px;
  left: 0;
  color: var(--dark-alternative);
  cursor: pointer;
}
.toggle-checkbox:checked ~ .popup {
  display: block;
}
.toggle-checkbox:checked ~ .toggle-label {
  opacity: 0;
}

@keyframes slideIn {
  0% {
    transform: translateX(200%);
    opacity: 0;
  }
  50% {
    transform: translateX(200%);
    opacity: 0;
