  padding: 0.7em 1.8em;
  border-radius: 10px;
  color: white;
  box-shadow: 0 0 10px var(--background);
}

.tooltip {
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  padding: 0.3em 0.6em;
  opacity: 0;
  pointer-events: none;
  transition: all 0.3s;
  background: var(--background);
  border-radius: 10px;
}

