  height: fit-content;
  display: flex;
  justify-content: center;
  align-items: center;
}

/*Banner */

.bannerContainer .banner {
  background-color: #e7e5df;
  height: 70px;
  width: 250px;
  border-radius: 10px;
  position: relative;
  overflow-y: hidden;
}

/*Loaders */

.bannerContainer .banner .loader {
  height: 100%;
  width: 100%;
  border-radius: 10px;
  position: absolute;
}

.bannerContainer .banner .loader1 {
  background-color: #393e41;
  animation: loader 0.5s linear 0s;
}

.bannerContainer .banner .loader2 {
  background-color: #44bba4;
  animation: loader 0.5s linear 0.2s;
}

.bannerContainer .banner .loader3 {
  background-color: #e7bb41;
  animation: loader 0.5s linear 0.3s;
}

/*Main card*/

.bannerContainer .banner .mainCard {
  width: 100%;
  background-color: #e7e5df;
  display: flex;
  justify-content: space-around;
  align-items: center;
  color: #393e41;
  font-weight: bolder;
  animation: loader 0.5s linear 0.4s;
  border-radius: 10px;
}

.bannerContainer .banner span {
  font-size: 29px;
  font-weight: 900;
  transform: translateY(-120px);
  animation: appear 0.1s ease-in 0.9s forwards;
}

.bannerContainer .banner svg {
  width: 30px;
  transform: translateY(-100px);
  animation: appear 0.1s ease-in 0.9s forwards;
}

.bannerContainer .banner .mainCard:hover > .secondCard {
  height: 100%;
  color: #e7e5df;
}

/* Second card */

.bannerContainer .banner .secondCard {
  background-color: #393e41;
  display: flex;
  justify-content: space-around;
  align-items: center;
  color: transparent;
  height: 0px;
  transition: all 0.3s ease-in-out;
  cursor: pointer;
}

/* Animations */

@keyframes loader {
  from {
    width: 0%;
  }

  to {
    width: 100%;
  }
}

@keyframes appear {
  from {
    transform: translateY(-100px);
  }

  to {
    transform: translateY(0px);
  }
}

